/* ---------------- MPASM-style assembler: absolute mode, default radix HEX, case-insensitive ---------------- */
const INC = { W:0, F:1, INDF:0, TMR0:1, PCL:2, STATUS:3, FSR:4, PORTA:5, PORTB:6, PORTC:7, PCLATH:0x0A, INTCON:0x0B, PIR1:0x0C, PIR2:0x0D,
  TMR1L:0x0E, TMR1H:0x0F, T1CON:0x10, TMR2:0x11, T2CON:0x12, ADRES:0x1E, ADCON0:0x1F, OPTION_REG:0x81, TRISA:0x85, TRISB:0x86, TRISC:0x87,
  PIE1:0x8C, PIE2:0x8D, PCON:0x8E, PR2:0x92, ADCON1:0x9F, C:0, DC:1, Z:2, RP0:5, RP1:6, GIE:7, PEIE:6, TMR1IF:0, TMR1IE:0, TMR1ON:0,
  PCFG0:0, PCFG1:1, PCFG2:2, T1CKPS0:4, T1CKPS1:5, TMR1CS:1 };
const OPS = 'ADDWF ANDWF CLRF CLRW COMF DECF DECFSZ INCF INCFSZ IORWF MOVF MOVWF NOP RLF RRF SUBWF SWAPF XORWF BCF BSF BTFSC BTFSS ADDLW ANDLW CALL CLRWDT GOTO IORLW MOVLW RETFIE RETLW RETURN SLEEP SUBLW XORLW'.split(' ');
function num(tok, sym){
  let m; const s = tok.trim();
  if ((m = /^0x([0-9a-f]+)$/i.exec(s))) return parseInt(m[1],16);
  if ((m = /^([0-9][0-9a-f]*)h$/i.exec(s))) return parseInt(m[1],16);
  if ((m = /^b'([01]+)'$/i.exec(s))) return parseInt(m[1],2);
  if ((m = /^d'(\d+)'$/i.exec(s)) || (m = /^\.(\d+)$/.exec(s))) return parseInt(m[1],10);
  if ((m = /^h'([0-9a-f]+)'$/i.exec(s))) return parseInt(m[1],16);
  if (/^[0-9][0-9a-f]*$/i.test(s)) return parseInt(s,16);          // MPASM default radix = hex
  const k = s.toUpperCase(); if (k in sym) return sym[k];
  throw new Error('undefined symbol '+s);
}
function expr(e, sym){ const parts = e.replace(/\s+/g,'').split(/(?=[+-])/); let v = 0;
  for (const p of parts){ if (p[0]==='-') v -= num(p.slice(1),sym); else if (p[0]==='+') v += num(p.slice(1),sym); else v += num(p,sym); } return v; }
function assemble(src){
  const sym = Object.assign({}, INC), macros = {}, prog = [], labels = {}, ram = {}, lines = src.split('\n');
  let loc = 0, inMac = null; const items = [];
  lines.forEach((raw, ln)=>{
    if (!raw.trim()) return;
    let label = null, rest = raw;
    if (!/^\s/.test(raw)){ const m = /^(\S+)\s*(.*)$/.exec(raw); label = m[1].replace(/:$/,''); rest = m[2]; }
    const m2 = /^\s*(\S+)\s*(.*)$/.exec(rest||''); const op = m2 ? m2[1].toUpperCase() : ''; const arg = m2 ? m2[2].trim() : '';
    if (inMac){ if (op==='ENDM') inMac = null; else macros[inMac].push(raw); return; }
    if (op==='MACRO'){ inMac = label.toUpperCase(); macros[inMac] = []; return; }
    if (op==='EQU'){ sym[label.toUpperCase()] = expr(arg, sym); return; }
    if (op==='RES'){ sym[label.toUpperCase()] = loc; ram[label.toUpperCase()] = loc; loc += expr(arg, sym); return; }
    if (op==='ORG'){ loc = expr(arg, sym); return; }
    if (label){ sym[label.toUpperCase()] = loc; labels[label.toUpperCase()] = {addr:loc, ln, name:label}; }
    if (!op || /^(ERRORLEVEL|#INCLUDE|LIST|END|__CONFIG|PROCESSOR|RADIX)$/.test(op)) return;
    if (macros[op]){ macros[op].forEach(ml=>{ const mm=/^\s*(\S+)\s*(.*)$/.exec(ml); items.push({addr:loc++, op:mm[1].toUpperCase(), arg:mm[2].trim(), ln, mac:op}); }); return; }
    if (OPS.indexOf(op) < 0) throw new Error('unknown op '+op+' line '+(ln+1));
    items.push({addr:loc++, op, arg, ln});
  });
  for (const it of items){
    const a = it.arg ? it.arg.split(',').map(s=>s.trim()) : [];
    const ins = { op:it.op, ln:it.ln, mac:it.mac||null, f:0, d:1, b:0, k:0, dflt:false, addr:it.addr };
    switch (it.op){
      case 'BCF': case 'BSF': case 'BTFSC': case 'BTFSS': ins.f = expr(a[0],sym); ins.b = expr(a[1],sym)&7; break;
      case 'CLRF': case 'MOVWF': ins.f = expr(a[0],sym); break;
      case 'CALL': case 'GOTO': ins.k = expr(a[0],sym); break;
      case 'ADDLW': case 'ANDLW': case 'IORLW': case 'MOVLW': case 'RETLW': case 'SUBLW': case 'XORLW': ins.k = expr(a[0],sym)&0xFF; break;
      case 'CLRW': case 'NOP': case 'CLRWDT': case 'RETFIE': case 'RETURN': case 'SLEEP': break;
      default: ins.f = expr(a[0],sym); if (a.length>1) ins.d = expr(a[1],sym)?1:0; else { ins.d = 1; ins.dflt = true; }
    }
    prog[it.addr] = ins;
  }
  const byAddr = {}; for (const k in labels){ const L=labels[k]; if (!(L.addr in byAddr)) byAddr[L.addr]=L.name; }
  return { prog, sym, labels, byAddr, ram, lines, words: items.length };
}

/* ---------------- PIC16F73 core: the instructions, banks, ports, Timer1 and its interrupt ---------------- */
function makeCPU(asm, env){
  const P = asm.prog;
  const S = { pc:0, w:0, mem:new Uint8Array(512), stack:new Uint16Array(8), sp:0, cyc:0, tmr1:0, pre:0 };
  S.mem[0x03] = 0x18; S.mem[0x85] = 0x3F; S.mem[0x86] = 0xFF; S.mem[0x87] = 0xFF; S.mem[0x81] = 0xFF;   // power-on reset values
  const ADDR = f => { const rp = (S.mem[3]>>5)&3; const a = (rp<<7)|(f&0x7F); const lo=a&0x7F;
    return (lo===0||lo===2||lo===3||lo===4||lo===0x0A||lo===0x0B) ? lo : a; };
  const rd = a => {
    switch (a){
      case 0x05: return S.mem[5] & ~S.mem[0x85] & 0x3F;
      case 0x06: return env.portb(S.cyc);
      case 0x07: { const tr=S.mem[0x87]; return (S.mem[7] & ~tr) | (env.portc(S.cyc) & tr); }
      case 0x0E: return S.tmr1 & 0xFF;
      case 0x0F: return (S.tmr1>>8) & 0xFF;
      default: return S.mem[a];
    }
  };
  const wr = (a, v) => {
    v &= 0xFF;
    switch (a){
      case 0x05: { const old = S.mem[5] & ~S.mem[0x85] & 0x3F; S.mem[5] = v; const nw = v & ~S.mem[0x85] & 0x3F; if (old!==nw) env.porta(S.cyc, nw, old); return; }
      case 0x0E: S.tmr1 = (S.tmr1 & 0xFF00) | v; S.pre = 0; return;
      case 0x0F: S.tmr1 = (S.tmr1 & 0x00FF) | (v<<8); S.pre = 0; return;
      case 0x85: { const old = S.mem[5] & ~S.mem[0x85] & 0x3F; S.mem[0x85] = v; const nw = S.mem[5] & ~v & 0x3F; if (old!==nw) env.porta(S.cyc, nw, old); return; }
      default: S.mem[a] = v;
    }
  };
  const Zf = v => { if ((v&0xFF)===0) S.mem[3] |= 4; else S.mem[3] &= ~4; };
  const tick = n => { S.cyc += n; const t1 = S.mem[0x10];
    if (t1 & 1){ const ps = 1 << ((t1>>4)&3); S.pre += n; while (S.pre >= ps){ S.pre -= ps; S.tmr1 = (S.tmr1+1) & 0xFFFF; if (S.tmr1===0) S.mem[0x0C] |= 1; } } };
  const push = v => { S.stack[S.sp & 7] = v; S.sp = (S.sp+1) & 7; };
  const pop = () => { S.sp = (S.sp+7) & 7; return S.stack[S.sp]; };
  function step(){
    const ic = S.mem[0x0B];
    if ((ic & 0x80) && (ic & 0x40) && (S.mem[0x8C] & S.mem[0x0C] & 1)){ push(S.pc); S.mem[0x0B] &= 0x7F; S.pc = 4; tick(3); if (env.irq) env.irq(S.cyc); return; }
    const I = P[S.pc];
    if (!I){ S.pc = (S.pc+1) & 0x1FFF; tick(1); return; }
    const pc0 = S.pc; S.pc = (S.pc+1) & 0x1FFF; let cy = 1; const fa = ADDR(I.f); let r;
    switch (I.op){
      case 'MOVF': r = rd(fa); Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'MOVWF': wr(fa, S.w); break;
      case 'MOVLW': S.w = I.k; break;
      case 'CLRF': wr(fa, 0); Zf(0); break;
      case 'CLRW': S.w = 0; Zf(0); break;
      case 'XORWF': r = rd(fa) ^ S.w; Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'ANDWF': r = rd(fa) & S.w; Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'IORWF': r = rd(fa) | S.w; Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'XORLW': S.w = (S.w ^ I.k) & 0xFF; Zf(S.w); break;
      case 'ANDLW': S.w = S.w & I.k; Zf(S.w); break;
      case 'IORLW': S.w = S.w | I.k; Zf(S.w); break;
      case 'ADDLW': { const s = S.w + I.k; S.mem[3] = (S.mem[3] & ~1) | (s>255?1:0); S.w = s & 0xFF; Zf(S.w); break; }
      case 'SUBLW': { const s = I.k - S.w; S.mem[3] = (S.mem[3] & ~1) | (s>=0?1:0); S.w = s & 0xFF; Zf(S.w); break; }
      case 'ADDWF': { const s = rd(fa) + S.w; S.mem[3] = (S.mem[3] & ~1) | (s>255?1:0); r = s & 0xFF; Zf(r); if (I.d) wr(fa,r); else S.w = r; break; }
      case 'SUBWF': { const s = rd(fa) - S.w; S.mem[3] = (S.mem[3] & ~1) | (s>=0?1:0); r = s & 0xFF; Zf(r); if (I.d) wr(fa,r); else S.w = r; break; }
      case 'COMF': r = (~rd(fa)) & 0xFF; Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'INCF': r = (rd(fa)+1) & 0xFF; Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'DECF': r = (rd(fa)+255) & 0xFF; Zf(r); if (I.d) wr(fa,r); else S.w = r; break;
      case 'INCFSZ': r = (rd(fa)+1) & 0xFF; if (I.d) wr(fa,r); else S.w = r; if (!r){ S.pc++; cy = 2; } break;
      case 'DECFSZ': r = (rd(fa)+255) & 0xFF; if (I.d) wr(fa,r); else S.w = r; if (!r){ S.pc++; cy = 2; } break;
      case 'RRF': { const v = rd(fa), c = S.mem[3] & 1; r = (v>>1) | (c<<7); S.mem[3] = (S.mem[3] & ~1) | (v & 1); if (I.d) wr(fa,r); else S.w = r; break; }
      case 'RLF': { const v = rd(fa), c = S.mem[3] & 1; r = ((v<<1) | c) & 0xFF; S.mem[3] = (S.mem[3] & ~1) | (v>>7); if (I.d) wr(fa,r); else S.w = r; break; }
      case 'SWAPF': { const v = rd(fa); r = ((v<<4)|(v>>4)) & 0xFF; if (I.d) wr(fa,r); else S.w = r; break; }
      case 'BSF': wr(fa, rd(fa) | (1<<I.b)); break;
      case 'BCF': wr(fa, rd(fa) & ~(1<<I.b)); break;
      case 'BTFSC': if (!(rd(fa) & (1<<I.b))){ S.pc++; cy = 2; } break;
      case 'BTFSS': if (rd(fa) & (1<<I.b)){ S.pc++; cy = 2; } break;
      case 'GOTO': S.pc = I.k; cy = 2; break;
      case 'CALL': push(S.pc); S.pc = I.k; cy = 2; if (env.call) env.call(pc0, I.k, S.cyc); break;
      case 'RETURN': S.pc = pop(); cy = 2; break;
      case 'RETLW': S.w = I.k; S.pc = pop(); cy = 2; break;
      case 'RETFIE': S.pc = pop(); S.mem[0x0B] |= 0x80; cy = 2; break;
      default: break;                                    // NOP, CLRWDT (watchdog config unknown), SLEEP
    }
    tick(cy);
  }
  const snap = () => ({ pc:S.pc, w:S.w, mem:S.mem.slice(), stack:S.stack.slice(), sp:S.sp, cyc:S.cyc, tmr1:S.tmr1, pre:S.pre });
  const load = z => { S.pc=z.pc; S.w=z.w; S.mem.set(z.mem); S.stack.set(z.stack); S.sp=z.sp; S.cyc=z.cyc; S.tmr1=z.tmr1; S.pre=z.pre; };
  return { S, step, snap, load };
}
const ASMC = {};
function getAsm(k){ if (!ASMC[k]){ const a = assemble(FW_SRC[k]); const M = a.sym.MAIN; const calls = [];
    for (let pc = M; pc < M+40; pc++){ const I = a.prog[pc]; if (!I) continue; if (I.op==='CALL') calls.push({pc, k:I.k, name:a.byAddr[I.k]||('0x'+I.k.toString(16))}); if (I.op==='GOTO' && I.k===M) break; }
    a.mainCalls = calls; a.hasIsr = !!(a.prog[4] && a.prog[4].op!=='RETFIE');
    a.watch = BASE_WATCH.concat(FW[k].watch).filter(n=>n in a.ram);
    ASMC[k] = a; }
  return ASMC[k]; }

