function dsub(cx, cy, n, male, pinFn, cls, title){
  // D-sub face as seen from behind the unit. Female: pin 1 top-right; male: pin 1 top-left.
  const top = n===9 ? 5 : 13, pitch = 21.8, rowGap = 22.4;
  const wTop = (top-1)*pitch + 34, wBot = (top-2)*pitch + 30, h = 74;
  const sx = 0.98, sc = n===9 ? 98.4 : 185.2;            // jack-screw spacing .984 / 1.852 in
  let s = `<g class="${cls}"><title>${title}</title>
    <rect x="${cx-wTop/2-62}" y="${cy-48}" width="${wTop+124}" height="96" rx="6" fill="#9a9ea3" stroke="#5d6165" stroke-width="2"/>
    <path d="M${cx-wTop/2},${cy-h/2} L${cx+wTop/2},${cy-h/2} L${cx+wBot/2},${cy+h/2} L${cx-wBot/2},${cy+h/2} Z" fill="${male?'#2a2c2e':'#1a1b1c'}" stroke="#c9cdd2" stroke-width="5" stroke-linejoin="round"/>
    ${[-1,1].map(sg=>`<circle cx="${cx+sg*sc}" cy="${cy}" r="13" fill="#b9bcc0" stroke="#6d7175" stroke-width="2"/><circle cx="${cx+sg*sc}" cy="${cy}" r="5" fill="#444"/>`).join('')}`;
  for (let p=1;p<=n;p++){
    const row = p<=top ? 0 : 1, idx = row ? p-top-1 : p-1, cnt = row ? n-top : top;
    let x = (idx - (cnt-1)/2)*pitch*sx; if (!male) x = -x;
    const y = cy + (row ? rowGap/2 : -rowGap/2) + (row?2:-2);
    const st = pinFn(p);
    s += `<g ${st.click?`class="p7pin" data-act="${st.click}" style="cursor:pointer"`:''}><title>${st.tip}</title><circle cx="${cx+x}" cy="${y}" r="${male?6.5:7}" fill="${st.col}" stroke="${male?'#d8dbe0':'#000'}" stroke-width="${male?1.5:2}"/>${st.click?`<circle cx="${cx+x}" cy="${y}" r="11" fill="transparent"/>`:''}</g>`;
  }
  return s + '</g>';
}
function rearSVG(t){
  const on = powerAt(t), w = wordAt(t), acc = 'var(--accent)', off = '#c9cdd2', hot = '#ffb43a';
  const opto = p => { for (let n=1;n<=8;n++){ const [pp, pm, lg] = J3[n-1]; const act = inActive(n,t);
      if (p===lg) return {col: act&&D.mode[n-1]==='logic'?acc:off, tip:`Pin ${p}: Logic ${n} (IN${n}) — ${act&&D.mode[n-1]==='logic'?'grounded':'open'} · click to toggle`, click:'L'+n};
      if (p===pp) return {col: act&&D.mode[n-1]==='opto'?(optoOn(n)?hot:'#a55'):off, tip:`Pin ${p}: Opto ${n}+ — ${act&&D.mode[n-1]==='opto'?D.volt[n-1]+' V applied':'no voltage'} · click to toggle`, click:'O'+n};
      if (p===pm) return {col:off, tip:`Pin ${p}: Opto ${n}− (return, through D${8+n} 1N4003)`}; }
    return {col:'#777', tip:'Pin 13: Ground'}; };
  const relay = p => { if (p===1) return {col:'#666', tip:'Pin 1: N/C'};
    for (let r=0;r<4;r++) for (let pl=0;pl<2;pl++){ const [c,no,nc] = J2[r][pl]; const k = contactAt(r,t) && on; const pole = pl?'B':'A';
      if (p===c) return {col:'#d9c27a', tip:`Pin ${p}: Common ${r+1}${pole}`};
      if (p===no) return {col:k?acc:off, tip:`Pin ${p}: Normally open ${r+1}${pole} — ${k?'connected to COM (relay energised)':'open'}`};
      if (p===nc) return {col:!k?'#6aa8d8':off, tip:`Pin ${p}: Normally closed ${r+1}${pole} — ${!k?'connected to COM':'open'}`}; }
    return {col:off, tip:'Pin '+p}; };
  const oc = p => { if (p===6) return {col:'#777', tip:'Pin 6: Ground'}; const n = J1.indexOf(p)+1; const v = on && outOn('OC'+n,t);
    return {col:v?acc:off, tip:`Pin ${p}: Open collector ${n} (ULN2803 U6, PCB net J1-${J1FP[n-1]}) — ${v?'sinking to ground':'off'}`}; };
  const audio = p => { const a = audAt(t);
    const m = {1:'Audio input +',2:'Audio input −',3:'Ground',4:'Open collector 9 (toggles while audio is on)',5:'Open collector 10 (on while audio is off)',6:'Audio output (speaker, 8 Ω)',7:'Ground',8:'Ground',9:'Control input — audio enable'};
    let col = off; if (p===4 && on && outOn('OC9',t)) col = acc; if (p===5 && on && outOn('OC10',t)) col = acc; if (p===9 && a) col = acc; if (p===6 && ampOn(t)) col = hot; if (p===3||p===7||p===8) col='#777';
    return {col, tip:`Pin ${p}: ${m[p]}${p===9?(a?' — grounded (amp enabled) · click to toggle':' — open (amp muted) · click to toggle'):''}`, click:p===9?'AUD':null}; };
  return `<svg viewBox="0 0 1713 321" role="img" aria-label="POD7 rear panel (real silkscreen)" style="width:100%;max-width:980px;border-radius:8px;display:block">
    <rect width="1713" height="321" rx="8" fill="${PANEL}"/>
    ${dsub(PX(1.735), PY(1.188), 9, false, audio, 'p7j', 'AUDIO I\\O — DB9 female (J5)')}
    ${dsub(PX(1.735), PY(.563), 25, false, opto, 'p7j', 'OPTO INPUTS — DB25 female (J3): click a Logic pin to ground it, an Opto + pin to apply the voltage set below')}
    ${dsub(PX(4.035), PY(.563), 25, true, relay, 'p7j', 'RELAY OUTPUTS — DB25 male (J2): 4 × 2-pole form C')}
    ${dsub(PX(5.885), PY(.563), 9, true, oc, 'p7j', 'O.C. OUTPUTS — DB9 male (J1)')}
    <g><title>Fuse holder: 115 VAC, 1/2 A slow-blow</title><circle cx="${PX(8.570-1.700)}" cy="${PY(.563)}" r="50" fill="#0b0c0d" stroke="#2e3134" stroke-width="3"/><circle cx="${PX(8.570-1.700)}" cy="${PY(.563)}" r="40" fill="#1a1b1d"/>
      <text x="${PX(8.570-1.700)}" y="${PY(.563)+7}" text-anchor="middle" font-size="20" font-weight="700" fill="#cfd2d6" transform="rotate(-20 ${PX(8.570-1.700)} ${PY(.563)})">FUSE</text></g>
    <g class="p7pwr" style="cursor:pointer"><title>Line cord through a strain-relief bushing (double-D .512 × .450) — click to switch the power</title><circle cx="${PX(8.570-.900)}" cy="${PY(.563)}" r="48" fill="#070808" stroke="#2e3134" stroke-width="3"/><rect x="${PX(8.570-.900)-12}" y="${PY(.563)-32}" width="24" height="64" rx="10" fill="#202224"/></g>
    <circle cx="${PX(8.570-1.300)}" cy="${PY(1.400)}" r="9" fill="#8f9295" stroke="#55585b" stroke-width="2"><title>PEM stud FH-440 (ground)</title></circle>
    ${[[.251,.803],[8.319,.803]].map(([x,y])=>`<circle cx="${PX(x)}" cy="${PY(y)}" r="11" fill="#8f9295" stroke="#55585b" stroke-width="2"/>`).join('')}
    <image href="${ASSET}pod7-rear-white.png" width="1713" height="321" style="pointer-events:none"/>
  </svg>`;
}
function bindPanel(root){
  root.querySelectorAll('.p7pwr').forEach(g=>g.addEventListener('click', ()=>A.power()));
  root.querySelectorAll('.p7trim').forEach(g=>{
    g.addEventListener('click', e=>{ const r=g.getBoundingClientRect(); A.trim((e.clientX-r.left)/r.width < 0.5 ? -0.05 : 0.05); });
    g.addEventListener('wheel', e=>{ e.preventDefault(); A.trim(e.deltaY<0 ? 0.05 : -0.05); }, {passive:false}); });
  root.querySelectorAll('.p7pin').forEach(g=>g.addEventListener('click', ()=>{ const a=g.dataset.act;
    if (a==='AUD') return A.aud(); const n=+a.slice(1); const want = a[0]==='O' ? 'opto' : 'logic';
    if (D.mode[n-1]!==want){ D.mode[n-1]=want; dirty(); } A.toggleIn(n); }));
}
