/* ---------------- software ---------------- */
function variantState(t){
  const g = n => ramAt(n,t), k = D.fw, rows = [];
  const b = (v,i)=> v===null ? '—' : ((v>>i)&1);
  if (k==='v100'||k==='v102') rows.push(['Mapping','fixed: SHOUT0 = f(OPTO), SHOUT1 relays = f(OPTO bits 7–4); OC9/OC10 from INPUT0']);
  if (k==='v102') rows.push(['OC9 flasher', `TOGGLE_COUNT ${g('TOGGLE_COUNT')} · TOGGLE_COUNT2 ${g('TOGGLE_COUNT2')} · TOGGLE_FLAG ${hex2(g('TOGGLE_FLAG'))} (OC9 lit when 0xFF)`]);
  if (k==='v103'||k==='c040a'||k==='c047'){ const rs=g('RELAY_STATUS'); [[7,'TEMP7','TEMP3'],[6,'TEMP6','TEMP_2'],[3,'TEMP5','TEMP_1'],[2,'TEMP4','TEMP0']].forEach(([bit,a,c],r)=>{ const va=ramAt(a,t), vc=ramAt(c,t);
      rows.push([`Relay ${r+1} (RELAY_STATUS,${bit})`, b(rs,bit)==1 ? `<b>HELD</b>${va!==null&&vc!==null?` — ${Math.max(0,(vc-1)*256+va)} passes left on ${c}:${a}`:''}` : 'idle']); }); }
  if (k==='c024'){ const s=g('RELAY_STATUS'), on=g('RELAY_STATUS_ON'), s1=g('RELAY_STATUS1'); [[7,'IN1/K1/OC1'],[6,'IN2/K2/OC2'],[3,'IN3/K3/OC3'],[2,'IN4/K4/OC4'],[5,'IN5/OC5'],[4,'IN6/OC6'],[1,'IN7/OC7'],[0,'IN8/OC8']].forEach(([bit,l])=>{
      rows.push([l, b(on,bit)==1 ? (b(s1,bit)==1?'<b>OFF-DELAY</b> (RELAY_STATUS1)':'<b>ON</b> (RELAY_STATUS_ON)') : (b(s,bit)==1?'<b>ON-DELAY</b> (RELAY_STATUS)':'idle')]); }); }
  if (k==='c040'||k==='c040a'){ const rt=g('RELAY_TEMP'), cl=g('RELAY_STATUS_CLOSED'); rows.push(['MIC state', b(cl,0)==1 ? (b(rt,7)==1?'<b>COUGH</b> (relays 1–3 open, 4 closed)':'<b>MIC ON</b> (RELAY_STATUS_CLOSED = 1)') : '<b>MIC OFF</b>']); rows.push(['RELAY_TEMP', bin8(rt)+' (bit = 0 → relay energised; bits 7,6,5,4 = K1–K4)']); }
  if (k==='c047'){ const f=g('RELAY_CLOSE_SEQ_FLAG'); rows.push(['Sequence', f===null?'—':(f&1)?'<b>SEQ 1</b> (logic input 1)':(f&2)?'<b>SEQ 2</b> (logic input 2)':'idle (OPEN_RELAY_OUTPUT every pass)']);
    rows.push(['Timer1 counters', `FIFTHOFSEC ${g('FIFTHOFSEC_COUNTER')} · ONESEC (really 60 s) ${g('ONESEC_COUNTER')} · THIRTYSEC ${g('THIRTYSEC_COUNTER')} · THREEMIN ${g('THREEMIN_COUNTER')} · THREEMIN_FLAG ${g('THREEMIN_FLAG')}`]); rows.push(['RELAY_TEMP', bin8(g('RELAY_TEMP'))]); }
  if (k==='ctv'){ const r=g('RELAY_ON'); rows.push(['RELAY_ON', bin8(r)+' — bits 0–3 low = relay 1–4 on; bit 6 on-pulse running, bit 7 off-pulse running']); rows.push(['Pulse timers', `RELAY1_1/1_2 ${g('RELAY1_1')}/${g('RELAY1_2')} · RELAY2_1/2_2 ${g('RELAY2_1')}/${g('RELAY2_2')} · START ${g('START')} · STOP ${g('STOP')}`]); }
  return rows;
}
function minutes047(){
  const E = emulate(); const tick = E.irq.length>2 ? (E.irq[E.irq.length-1]-E.irq[0])/(E.irq.length-1) : 31251*8*TCY + 30*TCY;
  const sec = 5*tick, min = 60*sec;
  const seq = [[['K1','now',0],['K2','3 min',3*min],['K3','4 min',4*min],['K4','5 min',5*min]], [['K1','30 s',30*sec],['K2','1 min',min],['K3','2 min',2*min],['K4','3 min',3*min]]];
  const W=640, H=120, X = s=>60+s/(6*60)*(W-80);
  let s = `<svg viewBox="0 0 ${W} ${H}" style="width:100%"><line x1="60" y1="96" x2="${W-20}" y2="96" stroke="var(--ink2)"/>${[0,1,2,3,4,5,6].map(mm=>`<line x1="${X(mm*60)}" y1="92" x2="${X(mm*60)}" y2="100" stroke="var(--ink2)"/><text x="${X(mm*60)}" y="112" font-size="10" text-anchor="middle" fill="var(--ink2)">${mm} min</text>`).join('')}`;
  seq.forEach((q,i)=>{ const y=24+i*36; s+=`<text x="4" y="${y+4}" font-size="11" fill="var(--ink)">input ${i+1}</text>`; q.forEach(([r,l,tt],j)=>{ s+=`<circle cx="${X(tt)}" cy="${y}" r="6" fill="var(--accent)"/><text x="${X(tt)+8}" y="${y+4-(j%2)*0}" font-size="10" fill="var(--ink)">${r} ${(tt).toFixed(1)} s</text>`; }); });
  return s + `</svg><p class="small muted">One Timer1 tick = ${fmtMs(tick)} ${E.irq.length>2?'(measured from the emulated ISR entries)':'(31 251 counts × 8 × 813.8 ns, plus ISR reload latency)'}; “1 second” = 5 ticks = ${sec.toFixed(4)} s, so “3 minutes” is really ${(3*min).toFixed(1)} s. The source comment uses 4.9 MHz and “250” counts.</p>`;
}
