    m.querySelector('#regs').innerHTML = S ? `PC 0x${S.pc.toString(16).padStart(3,'0')} · W ${hex2(S.w)} · STATUS ${bin8(S.mem[3])} · PORTA ${paAt(t).toString(2).padStart(6,'0')} · ${FW[D.fw].file.split('/').pop()}` : 'PIC not running at the playhead';
    m.querySelector('#vs').innerHTML = `<table class="kv">${variantState(t).map(([a,b])=>`<tr><th>${a}</th><td class="small">${b}</td></tr>`).join('')}</table>`;
    m.querySelector('#m47').innerHTML = D.fw==='c047' ? '<h3>047 over six minutes</h3>'+minutes047() : '';
    const w = wordAt(t), sh0 = ramAt('SHOUT0',t), sh1 = ramAt('SHOUT1',t);
