/* ---------------- findings ---------------- */
let FIND = null;
function measureAll(){
  if (FIND) return FIND; FIND = {};
  for (const k of FW_ORDER){ const asm = getAsm(k); let sr=0, last=-1, tog=[], passes=0; const M=asm.sym.MAIN;
    let lat=-1, blip=null, bt=null; const env = { portb:()=>0xFF, portc:()=>0xFD, porta:(c,v,o)=>{ if ((v&4)&&!(o&4)) sr=((sr<<1)|((v>>1)&1))&0xFFFF; if (v&1){ if (sr!==lat){ if (lat===0xFFFF && blip===null) blip=(c-bt)*TCY; if (sr===0xFFFF && bt===null) bt=c; lat=sr; } const b=(sr>>OUT.OC9)&1; if (b!==last){ tog.push(c); last=b; } } } };
    const cpu = makeCPU(asm, env); const end = Math.round(2.0/TCY); let first=null, pc=0;
    while (cpu.S.cyc < end){ if (cpu.S.pc===M){ passes++; if (first===null) first=cpu.S.cyc; pc=cpu.S.cyc; } cpu.step(); }
    const per = (pc-first)/Math.max(1,passes-1); const halves = tog.slice(2).map((c,i,a)=>i?c-a[i-1]:null).filter(x=>x);
    FIND[k] = { cyc: per, half: halves.length? halves.reduce((a,b)=>a+b,0)/halves.length*TCY : null, blip }; }
  return FIND;
}
function viewNotes(m){
  window.__pod7Active = false;
  const F = measureAll(); const hz = k => F[k].half ? (1/(2*F[k].half)).toFixed(2)+' Hz' : 'steady';
  const hold103 = (255+15*256)*F.v103.cyc*TCY, hold024 = (255+31*256)*F.c024.cyc*TCY;
  m.innerHTML = card('What POD7 and its firmware are up to — findings from the source', `
  <ol>
    <li><b>OC9 does not flash at 2 Hz.</b> The manual says OC9 “toggles at 2 Hz”. PROCESS flips TOGGLE_FLAG every 255 (TOGGLE_COUNT) × 8 (TOGGLE_COUNT2) = 2040 main-loop passes, so the rate depends on how long a pass is. Running each build at 4.9152 MHz: v1.02 ${F.v102.cyc.toFixed(1)} cycles/pass → <b>${hz('v102')}</b>; v1.03 ${F.v103.cyc.toFixed(1)} → ${hz('v103')}; 040 V101 → ${hz('c040')}; 047 → ${hz('c047')}; 024 ${F.c024.cyc.toFixed(1)} → ${hz('c024')}. Every routine added to the loop slowed the flasher. v1.00 has no flasher at all (OC9 is steady).</li>
    <li><b><span class="mono">HOLD EQU 10</span> means sixteen.</b> MPASM’s default radix is hex and no <span class="mono">LIST R=DEC</span> is given; the 047 listing inside <span class="mono">pod7-047.rar</span> confirms <span class="mono">HOLD = 00000010</span>. So the v1.03 hold is 255 + 15 × 256 = 4095 passes ≈ ${hold103.toFixed(2)} s, and 024’s <span class="mono">HOLD EQU 20</span> (= 32) is 8191 passes ≈ ${hold024.toFixed(2)} s — which matches its “2 sec delay” comment, so it was probably tuned on the bench ${inf}.</li>
    <li><b>The “delayed release” is not a fixed delay.</b> In <span class="mono">HOLD_RELAY</span> (v1.03, 040 V100, 047) TEMP7/TEMP3 etc. count down on every pass while the relay is held and are never reloaded when the input is pressed again. After release the relay stays on for whatever is left of the current count: anywhere from 0 to ≈${hold103.toFixed(2)} s. Use the “v1.03” scenario and tap IN1 at different moments.</li>
    <li><b>A jump that goes backwards.</b> In <span class="mono">HOLD_RELAY</span>, <span class="mono">DECFSZ TEMP_2,F / GOTO NEXT_RELAY</span> (relay 2) and <span class="mono">DECFSZ TEMP_1,F / GOTO NEXT_RELAY</span> (relay 3) jump back to relay 2’s block instead of forward. Each roll-over of relay 3’s counter re-runs relay 2 and takes an extra count off TEMP6, so relay 2’s hold is shortened whenever relay 3 is held too.</li>
    <li><b>Dead relay code in v1.03.</b> PROCESS ends its OC section with <span class="mono">return</span>; the relay block after it (with <span class="mono">btfsc relay_status,7</span> and <span class="mono">BsF PORTA,3 ;TEST</span>) can never run. The same unreachable block is carried into 024 and 047.</li>
    <li><b>pod7c103.asm and pod7v103.asm are the same program.</b> They differ only by <span class="mono">XORWF PORTB</span> versus <span class="mono">XORWF PORTB,F</span>. MPASM defaults the destination to F (the .ERR files log “Message[305] Using default destination of 1 (file)”), so both assemble to identical code.</li>
    <li><b>SCAN is not a debounce.</b> It reads PORTB six times, two instructions apart, and gives up the pass if any two reads differ. The whole window is about 20 µs, far shorter than any contact bounce, and <span class="mono">XORWF PORTB,F</span> writes the comparison result into the input port’s latch each time. <span class="mono">BOUNCE</span>, <span class="mono">BOUNCE0–2</span> and <span class="mono">DBNC</span> are declared and initialised in every build but never used. Turn on “contact bounce” to watch OC2 chatter with the switch.</li>
    <li><b>Every output blips at power-up.</b> INIT loads <span class="mono">SHOUT0 = SHOUT1 = 0xFF</span> and calls REFRESH twice before the first pass. With the 4094 OE pins tied high (PCB note “*1 add a jumper between pin 15 and 16 on U7 and U9”), all ten OCs and all four relay coils turn on for ${fmtMs(F.v102.blip||0)} in v1.02 (${fmtMs(F.v103.blip||0)} in v1.03, whose relay bits are cleared only by HOLD_RELAY). The relays are too slow to close, but the open collectors do sink. See the “Power-up” scenario.</li>
    <li><b>Bank slips hidden by <span class="mono">ERRORLEVEL -302</span>.</b> INIT executes <span class="mono">BCF PORTC,0 ;TEST</span> with BANK1 selected, so it actually clears TRISC bit 0. v1.03’s <span class="mono">bcf porta,5 / BCF PORTA,3</span> also land on TRISA. The emulator follows the real banking, so you can see it in the RAM.</li>
    <li><b>The TEST pins go nowhere.</b> v1.03, 024 and 040 V100 pulse RA5/RA3 (“;TEST”). In POD7-iss2.net, PIC pins 5 (RA3) and 7 (RA5) have no net, so those pulses were for a scope probe on the bare pin.</li>
    <li><b>IN1 has no pull-up in the ISS2 netlist.</b> The ECO of 28 Apr 2008|41 renumbered RN1. IN8…IN2 moved to RN1-2…8, IN1’s connection was deleted and never added back, and RN1-9 was left empty. No build writes OPTION_REG, so PORTB’s weak pull-ups stay off. Unless the PCB differs from the netlist ${inf}, an unconnected IN1 floats. See the “IN1 pull-up missing” scenario.</li>
    <li><b>The O.C. OUTPUTS pin order is a mirror image.</b> The same ECO re-pinned J1 1↔5, 2↔4, 6↔9, 7↔8. The footprint is <span class="mono">DB9RF</span> (female), but the rear photo shows a male connector. On the real male connector OC1 is pin 5 and ground is pin 6, exactly as the manual says, while the PCB nets read J1-1 and J1-9 ${inf}. On the same day OUT1/OUT2 (OC9/OC10) were swapped on U8.</li>
    <li><b>Manual disagreements.</b> Open-collector current is “250 mA” in the specifications but “150 mA sink” in the I/O table. The relays are called “form C”, but each one has two poles (1A/1B …). The flash rate is covered in item 1.</li>
    <li><b>Opto inputs run hot at the top of the range.</b> At 28 V, R27–R34 (300 Ω) pass (28 − 2) / 300 ≈ 87 mA and dissipate 2.3 W. That is why the ECO of 25 Apr 2008 changed them from 1 W to 3 W parts. 87 mA is also above the usual opto-LED rating ${inf}.</li>
    <li><b>AUDIO LEVEL has two different ranges.</b> On the 1998 Issue 1 drawing, R8 (the bottom of the RV1 divider) is 100 Ω, which gives about ${(()=>{ const r=D.r8; D.r8='100R'; const a=D.trim; D.trim=1; const g1=audioGain(); D.trim=0; const g0=audioGain(); D.trim=a; D.r8=r; return (20*Math.log10(g1/g0)).toFixed(0); })()} dB of range. In the ISS2 netlist R8 is 100 kΩ, which leaves only ${(()=>{ const r=D.r8; D.r8='100K'; const a=D.trim; D.trim=1; const g1=audioGain(); D.trim=0; const g0=audioGain(); D.trim=a; D.r8=r; return (20*Math.log10(g1/g0)).toFixed(1); })()} dB. Probably a value slip ${inf}; try both in Setup.</li>
    <li><b>RS-485 hardware with no firmware.</b> U1/U2 (DS75176), J4 (the functional diagram calls it the “internal programming connector”) and the PIC’s RC6/RC7/RC2 (TX/RX/CS) are all wired. The manual offers “RS422/485 serial control” as a factory option. No archived build touches TXSTA, RCSTA or SPBRG, and U2’s RO and DI pins have no net.</li>
    <li><b>Custom 024 latches on a glitch.</b> HOLD_RELAY_ON sets <span class="mono">RELAY_STATUS</span> the first time it sees the input, and the on-delay then runs whether or not the input stays. A 1 ms spike turns the output on ≈2.2 s later and off ≈2.2 s after that (“024 glitch” scenario + Next second). It also delays the OCs, and inputs 5–8, not only the relays.</li>
    <li><b>Why 040 went to V101.</b> In 040 V100, COUGH only clears RELAY_TEMP. The relays still go through v1.03’s hold, so a cough shorter than the remaining count never opens them (“040 V100” scenario). V101 replaced HOLD_RELAY with a direct copy and COUGH works at once ${inf} as the motive. V101 also leaves a useless <span class="mono">MOVF RELAY_TEMP,0</span> at the end of POD7_CUSTOM_040.</li>
    <li><b>047’s comments are out of step with its code.</b> The header still reads “Delayed release of the relays” (copied from v1.03). The routine header says “Customization 047 for CTV”, although the README says the customer is not recorded. It says “When Logic Input 1 is high”, but the code acts when OPTO bit 7 is low (input asserted). <span class="mono">ONESEC_COUNTER</span> actually counts 60 seconds. The ISR comment computes with 4.9 MHz and “250” counts; with the real 31 251 counts at 4.9152 MHz, “1 second” is 1.017 s and “5 minutes” about 305 s. <span class="mono">CLOSE_RELAY_OUTPUT</span>, <span class="mono">RELAY_STATUS_CLOSED</span> and <span class="mono">TIMER1_ROLLOVER_COUNTER</span> are never used. C047_TIMER1_ON runs <span class="mono">CLRF PIR1</span> on every pass, and the author flagged <span class="mono">SKIP_COUNTER</span> as a “potential bug”: TMR1 is reloaded in the ISR without counting the latency, so each tick runs a little long.</li>
    <li><b>Version labels.</b> <span class="mono">POD7V101.ASM</span>’s header still says “VERSION 1.00”, and its .ERR file shows MPASM overriding <span class="mono">LIST P=16C73A</span> from the command line. The 1998 schematic names a <b>PIC16C63A</b>. The firmware says 16C73A (v1.00/1.01) and then 16F73. The ISS2 netlist uses the 16F73.</li>
    <li><b>Duplicates and strays.</b> <span class="mono">POD7 - #PCB/</span> and <span class="mono">POD7 - #iss2 #PCB/</span> are identical. The Issue 1 schematic PDFs appear three times (#PCB, POD 7 - Schematic, and a 3-page copy in #PCB #OBSOLETE) and sit beside the Issue 2 netlist. <span class="mono">POD7 - Functional Diagram.cdr</span> and <span class="mono">POD7 - #Functional Diagram.cdr</span> are identical, and so are the two copies of <span class="mono">pod7-047.rar</span>. The rear-panel drawing exists as <span class="mono">POD7-REAR ISS 1 (PANEL).pdf</span> (2015) and <span class="mono">…(PANEL) .pdf</span> (2016, stored rotated 270°, drops the “OR FH-440-6” stud option). The CTV folder holds a <span class="mono">POD7V103.ERR</span> from another build.</li>
  </ol>`) + card('Assumptions in this simulation', `<ul class="small">
    <li>The PIC core runs the archived source exactly (all instructions, banking, Timer1, the interrupt). Not modelled: the watchdog (config bits unknown, so CLRWDT is a no-op), Q-cycle sub-timing, and brown-out.</li>
    <li>Power-up timer 72 ms; relay operate 6 ms / release 3 ms; opto threshold 1 mA with 1.25 V LED + 0.75 V diode drops; floating input = 60 Hz square; contact bounce = 1.5 ms of random chatter. All ${inf}.</li>
    <li>Amplifier: ideal op-amp gains from the netlist resistor values, clipping at ±14 V peak ${inf}. The PIC never sees the audio.</li>
    <li>The unit has been running for ${PRE} s before t = 0 (pre-roll), so free-running counters are mid-count, as they would be on a real unit.</li></ul>`)
  + card('Sources', `<ul class="small mono">
    <li>#POD #SERIES/POD7 - #Master/POD7 - #Engineering/POD7 - #SOFTWARE/… (all .asm/.ERR/.PJT listed in the file header; pod7-047.rar → pod7v100.lst)</li>
    <li>…/POD7 - #PCB/POD7-iss2.net, POD7-iss2.ECO, POD7-iss2.pcb (notes), pod7_1..3.pdf · POD7 - Functional Diagram.cdr</li>
    <li>…/POD7 - #MANUAL/POD7MANU.pdf, CUSTOM/POD7-040/POD7-040.doc</li>
    <li>…/POD7 - #ARTWORK #DA #2016/POD7-FRONT&amp;REAR-SILK (CURVE).pdf, Pics/POD7 Front.jpg, POD7 REAR.jpg · …/POD7 - #Mechanical #DA #2016/POD7-FRONT ISS 1, POD7-REAR ISS 1 (PANEL).pdf</li></ul>`);
}

